(7095892, 1080474, 114285, '<td valign="top">Love the scene looking forward to seeing where in Europe this is, if at all it is in Europe. I''m wondering if people will think this is a texture and not grain it would of done well in the painting challenge.</td>', 'Love the scene looking forward to seeing where in Europe this is, if at all it is in Europe. I''m wondering if people will think this is a texture and not grain it would of done well in the painting challenge.', '2013-08-31 10:36:41.000000', NULL, 1),
(7095900, 1080746, 83313, '<td valign="top">I''m afraid the view from the usual perspective of standing hurts this interesting subject for me.</td>', 'I''m afraid the view from the usual perspective of standing hurts this interesting subject for me.', '2013-08-31 11:23:54.000000', NULL, 1),
(7095902, 1080484, 83313, '<td valign="top">Looks like he is relating stories of his past adventures. When he paused for effect, you snapped his pic. Great environmental portrait!</td>', 'Looks like he is relating stories of his past adventures. When he paused for effect, you snapped his pic. Great environmental portrait!', '2013-08-31 11:26:26.000000', NULL, 1),
(7095903, 1080619, 83313, '<td valign="top">I haven''t a clue what this is, but that is the point, right? Making me stop and look longer is always worth extra pointage. Well done.</td>', 'I haven''t a clue what this is, but that is the point, right? Making me stop and look longer is always worth extra pointage. Well done.', '2013-08-31 11:29:15.000000', NULL, 1),
(7095905, 1080779, 83313, '<td valign="top">My first impression was to ask why you turned it upside down. Then I realized these figures look quite menacing and this is probably the perspective of someone they are attacking. Your title supports that idea. Good work on this!</td>', 'My first impression was to ask why you turned it upside down. Then I realized these figures look quite menacing and this is probably the perspective of someone they are attacking. Your title supports that idea. Good work on this!', '2013-08-31 11:32:32.000000', NULL, 1),
(7096055, 1080659, 161988, '<td valign="top">Oh aren''t you the clever one! 9 from me!</td>', 'Oh aren''t you the clever one! 9 from me!', '2013-08-31 20:30:39.000000', NULL, 1),
(7096056, 1080612, 1031, '<td valign="top">I haven''t seen an engine with a crank-starter in a long time!</td>', 'I haven''t seen an engine with a crank-starter in a long time!', '2013-08-31 20:34:51.000000', NULL, 1),
(7096057, 1080659, 1031, '<td valign="top">Malicious little beasts, aren''t they. ;-)</td>', 'Malicious little beasts, aren''t they. ;-)', '2013-08-31 20:38:29.000000', NULL, 1),
(7096066, 1080654, 136989, '<td valign="top">Wonderful scene.  So many components ... Great b/w and contrast, reflections and gratuitous duckies!  Love it!</td>', 'Wonderful scene.  So many components ... Great b/w and contrast, reflections and gratuitous duckies!  Love it!', '2013-08-31 21:05:23.000000', NULL, 1),
(7096069, 1080772, 136989, '<td valign="top">This is a terrific comp.  I love how the shore bird watches the ship off in the distance.  The grain adds feeling here and doesn''t feel forced.</td>', 'This is a terrific comp.  I love how the shore bird watches the ship off in the distance.  The grain adds feeling here and doesn''t feel forced.', '2013-08-31 21:07:03.000000', NULL, 1),
(7096071, 1080773, 136989, '<td valign="top">I think cemeteries are supposed to be photographed in b/w with let''s of grain.  Just like this.  Makes the shots dramatic and feel like the past. Very nice.</td>', 'I think cemeteries are supposed to be photographed in b/w with let''s of grain.  Just like this.  Makes the shots dramatic and feel like the past. Very nice.', '2013-08-31 21:08:42.000000', NULL, 1),
(7096074, 1080789, 136989, '<td valign="top">I like the stark contrast of leaves with the background.  The grain adds a dramatic touch that I just love here.</td>', 'I like the stark contrast of leaves with the background.  The grain adds a dramatic touch that I just love here.', '2013-08-31 21:10:30.000000', NULL, 1),
(7096075, 1080283, 136989, '<td valign="top">This is my favorite PC in ths challenge. Up close and personal in grainy cowboy detail.   Awesome!</td>', 'This is my favorite PC in ths challenge. Up close and personal in grainy cowboy detail.   Awesome!', '2013-08-31 21:11:52.000000', NULL, 1),
(7096280, 1080677, 167332, '<td valign="top">cool shot. no frame would be better.</td>', 'cool shot. no frame would be better.', '2013-09-01 05:52:16.000000', NULL, 1),
