(7096353, 1080648, 35545, '<td valign="top">Nice detail in the back feathers.</td>', 'Nice detail in the back feathers.', '2013-09-01 11:01:21.000000', NULL, 1),
(7096355, 1080664, 35545, '<td valign="top">Lovely colors and interesting bokeh.</td>', 'Lovely colors and interesting bokeh.', '2013-09-01 11:01:47.000000', NULL, 1),
(7096383, 1080758, 63218, '<td valign="top">I see it! And I like the way you did your grainy PP.</td>', 'I see it! And I like the way you did your grainy PP.', '2013-09-01 11:48:08.000000', NULL, 1),
(7096387, 1080739, 94815, '<td valign="top">Nicely framed.</td>', 'Nicely framed.', '2013-09-01 11:57:22.000000', NULL, 1),
(7096389, 1080774, 94815, '<td valign="top">Scale is a little confounding, tones cooly darkish, with grain and gritty textures dominating - a kind of surreally expressionistic noirish scene - the car and its contents diminished to a mere toy in this harsh landscape.</td>', 'Scale is a little confounding, tones cooly darkish, with grain and gritty textures dominating - a kind of surreally expressionistic noirish scene - the car and its contents diminished to a mere toy in this harsh landscape.', '2013-09-01 12:05:58.000000', NULL, 1),
(7096390, 1080511, 94815, '<td valign="top">Rough ride?</td>', 'Rough ride?', '2013-09-01 12:06:47.000000', NULL, 1);
